    /// passes, the error's kind is `JobTimeout` and [`Error::job_status`] holds the last status.
    /// Every poll sends the client's query defaults. Dropping the future stops it.
    pub async fn wait_for_export(
        &self,
        tracking_id: &str,
        options: crate::runtime::WaitOptions,
    ) -> Result<models::Or14Response200, Error> {
        let request = Request::new(&O_R14)
            .path("tracking_id", &tracking_id)
            .params(&OrdersGetExportParams::default());
        self.transport.wait(&O_R14_JOB, request, options).await
    }

